(()=>{const $=id=>document.getElementById(id);const usd=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);const names=['Today · one crew','Same customers, smarter routes','Your growth plan'];if($('time-chart'))$('time-chart').innerHTML=names.map((n,i)=>`<div class="chart-row"><div class="bar-label" id="label-${i}"></div><div class="bar" id="bar-${i}"><span class="service"></span><span class="travel"></span><span class="admin"></span></div><small id="detail-${i}"></small></div>`).join('');function calculate(){if(!$('time-chart'))return;const c=+$('customers').value,p=+$('price').value,a=+$('added').value,e=+$('efficiency').value/100,k=+$('crews').value,total=c+a,capacity=Math.floor((160*k-10)*60/(30+15*(1-e))/2);$('customers-out').textContent=c;$('price-out').textContent=usd(p);$('added-out').textContent=a;$('efficiency-out').textContent=Math.round(e*100)+'%';$('crews-out').textContent=k;$('revenue').textContent=usd(total*2*p);$('revenue-delta').textContent='+'+usd(a*2*p)+' vs. today';$('capacity').textContent=capacity;$('capacity-note').textContent='Customers at two visits / month';$('fuel').textContent=usd(c*2*15/60*25/18*3.5*e);const rows=[[c,15,20,160],[c,15*(1-e),10,160],[total,15*(1-e),10,160*k]];const max=Math.max(160*k,...rows.map(([q,t,d])=>q*2*(30+t)/60+d));rows.forEach(([q,t,d,b],i)=>{let s=q,travel=q*2*t/60,used=s+travel+d;document.getElementById('label-'+i).textContent=names[i]+' · '+Math.round(used)+' / '+b+' hours';[s,travel,d].forEach((v,j)=>document.getElementById('bar-'+i).children[j].style.width=v/max*100+'%');document.getElementById('detail-'+i).textContent=Math.round(s)+' service · '+Math.round(travel)+' travel · '+d+' admin · '+Math.round(Math.max(0,b-used))+' available';});$('capacity-status').textContent=total>capacity?'This scenario exceeds capacity by '+(total-capacity)+' customers. Add a crew or adjust your plan.':(capacity-total)+' customer slots remain in this scenario.';$('time-chart').setAttribute('aria-label',names.map((n,i)=>n+': '+document.getElementById('detail-'+i).textContent).join('; '));}['customers','price','added','efficiency','crews'].forEach(id=>$(id)?.addEventListener('input',calculate));calculate();$('print-plan')?.addEventListener('click',()=>window.print());$('assessment-form')?.addEventListener('submit',event=>{event.preventDefault();const c=+$('a-clients').value,r=+$('a-revenue').value,costText=$('a-costs').value,recText=$('a-recurring').value,cost=costText===''?null:+costText,rec=recText===''?null:+recText;const result=$('assessment-result');result.hidden=false;const facts=[`${c} active customers`,`${usd(r*12)} annualized collected revenue, if this month repeats.`,`${usd(r/c)} average monthly revenue per customer.`];if(rec!==null)facts.push(`Approximately ${Math.round(c*rec/100)} customers on recurring plans.`);if(cost!==null)facts.push(`${usd(r-cost)} monthly operating surplus before omitted costs, tax and owner compensation.`);result.innerHTML='<h3>Your business snapshot</h3><ul>'+facts.map(x=>'<li>'+x+'</li>').join('')+'</ul><p>Build value with documented earnings, consistent customer retention and transferable service agreements.</p><div class="actions"><a class="button dark" href="early-access.html">Join early access</a><a class="text-link" href="growth.html">Explore my growth</a></div>';window.mmSnapshot={customers:c,monthly_revenue:r};if(cost!==null)window.mmSnapshot.monthly_costs=cost;if(rec!==null)window.mmSnapshot.recurring_percent=rec;if(document.getElementById('share-snapshot-row'))document.getElementById('share-snapshot-row').hidden=false;if($('customers'))$('customers').value=Math.min(200,Math.max(10,c));calculate();window.mmTrack?.('assessment_completed');result.focus({preventScroll:true});result.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});});})();

(()=>{const messages={customer:'New inquiry near Tuesday’s route. Property details need confirmation. Suggested next step: prepare an eligible quote for owner review.',routing:'Example: a weather delay affects three stops. Suggested next step: review a revised route that keeps nearby customers together and respects crew capacity.',company:'Example: retention fell in a service area. Suggested next step: review cancellations and service costs before launching a neighborhood campaign.'};document.querySelectorAll('[data-agent]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-agent]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',b===button?'true':'false');});document.getElementById('agent-message').textContent=messages[button.dataset.agent];}));})();
